// src/services/supplierInvoiceService.js
// Money the business OWES to a supplier/contractor who did work for it or
// provided something (opposite direction of jobs/clients, which is money
// owed TO the business). Mirrors jobService.js exactly on purpose — same
// shape, same conventions — so the "how much is left to pay" logic in
// calculations.js can reuse the identical pattern it already uses for jobs.
import {
  collection, doc,
  setDoc, updateDoc, deleteDoc,
  getDocs, onSnapshot, query, orderBy,
  serverTimestamp,
} from "firebase/firestore";
import { db } from "../config/firebase";

const col = (uid) => collection(db, "users", uid, "supplierInvoices");

export const supplierInvoiceService = {
  async getAll(userId) {
    const q = query(col(userId), orderBy("date", "desc"));
    const snap = await getDocs(q);
    return snap.docs.map((d) => ({ id: d.id, ...d.data() }));
  },

  // Live-subscribe — see equipmentService.js for the full contract.
  subscribe(userId, onData, onError) {
    const q = query(col(userId), orderBy("date", "desc"));
    return onSnapshot(
      q,
      (snap) => onData(snap.docs.map((d) => ({ id: d.id, ...d.data() }))),
      onError
    );
  },

  // Returns { id, promise } — see equipmentService.js for why.
  add(userId, data) {
    const ref = doc(col(userId));
    const promise = setDoc(ref, {
      ...data,
      // ISO string (not serverTimestamp) — see jobService.js for why.
      createdAt: new Date().toISOString(),
      updatedAt: serverTimestamp(),
    });
    return { id: ref.id, promise };
  },

  update(userId, id, data) {
    return updateDoc(doc(col(userId), id), { ...data, updatedAt: serverTimestamp() });
  },

  remove(userId, id) {
    return deleteDoc(doc(col(userId), id));
  },
};
